    "titleEn": "Botswana passes Industrial Development amendment to align cannabis manufacturing rules",
    "summary": "보츠와나 의회는 2026년 7월 22일 Industrial Development (Amendment) Bill 2026을 통과시켜 2019년 산업개발법을 Cannabis Act 2025와 정합화했다. 개정의 핵심은 Cannabis Act가 규율하는 대마 제조·가공 활동을 산업개발법 적용 대상에서 명시적으로 제외해 규제 중복과 불확실성을 줄이는 것이다. 보츠와나의 대마 체계는 의료·과학·연구·산업 목적에 한정되며 오락용은 금지된다. 따라서 이번 조치는 오락용 합법화가 아니라 제한적 합법 체계의 시행을 위한 후속 정비다.",
    "summaryEn": "Botswana’s Parliament passed the Industrial Development (Amendment) Bill, 2026 on 22 July, aligning the 2019 Industrial Development Act with the Cannabis Act 2025. The official Hansard says the consequential amendment expressly excludes cannabis-related manufacturing and processing regulated under the Cannabis Act from the Industrial Development Act, avoiding overlapping mandates and regulatory uncertainty. It supports implementation of Botswana’s controlled cannabis framework, which permits cultivation, production, distribution and trade only for medicinal, scientific, research and industrial purposes; recreational use remains prohibited. The measure is therefore a legislative harmonization step, not recreational legalization or an unlimited commercial opening.",
